// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette{value: 10 ether}(); }
    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(amount <= 10 ether);
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        vm.deal(actor, amount);
        vm.prank(actor);
        (bool ok, ) = address(c).call{value: amount}("");
        // General rule: a successful fallback call implies exactly 10 ether was sent.
        assertTrue(!ok || amount == 10 ether, "accepted call must carry exactly 10 ether");
    }
}
